import { Injectable, UnauthorizedException } from '@nestjs/common';
import { JwtService } from '@nestjs/jwt';
import { PrismaService } from '../prisma/prisma.service';
import { AuditService } from '../audit/audit.service';
import * as bcrypt from 'bcrypt';

@Injectable()
export class AuthService {
  constructor(
    private prisma: PrismaService,
    private jwtService: JwtService,
    private audit: AuditService,
  ) {}

  async validateUser(email: string, pass: string): Promise<any> {
    const user = await this.prisma.user.findUnique({ where: { email } });
    if (
      user &&
      user.status === 'ACTIVE' &&
      (await bcrypt.compare(pass, user.passwordHash))
    ) {
      const { passwordHash: _, ...result } = user;
      return result;
    }
    return null;
  }

  async login(user: any) {
    const payload = {
      email: user.email,
      sub: user.id,
      companyId: user.companyId,
    };

    const accessToken = this.jwtService.sign(payload, { expiresIn: '15m' });
    const refreshToken = this.jwtService.sign(payload, { expiresIn: '7d' });

    await this.prisma.user.update({
      where: { id: user.id },
      data: {
        refreshToken: await bcrypt.hash(refreshToken, 10),
        lastLoginAt: new Date(),
      },
    });

    await this.audit.logEvent({
      actorId: user.id,
      action: 'LOGIN',
      module: 'Auth',
      entityType: 'User',
      entityId: user.id,
    });

    return {
      access_token: accessToken,
      refresh_token: refreshToken,
    };
  }

  async logout(userId: string) {
    await this.prisma.user.updateMany({
      where: { id: userId, refreshToken: { not: null } },
      data: { refreshToken: null },
    });

    await this.audit.logEvent({
      actorId: userId,
      action: 'LOGOUT',
      module: 'Auth',
      entityType: 'User',
      entityId: userId,
    });
  }

  async refreshTokens(userId: string, refreshToken: string) {
    const user = await this.prisma.user.findUnique({ where: { id: userId } });
    if (!user || !user.refreshToken) {
      throw new UnauthorizedException('Access Denied');
    }

    const refreshTokenMatches = await bcrypt.compare(
      refreshToken,
      user.refreshToken,
    );
    if (!refreshTokenMatches) {
      throw new UnauthorizedException('Access Denied');
    }

    return this.login(user);
  }
}

import {
  Injectable,
  ExecutionContext,
  UnauthorizedException,
} from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  canActivate(context: ExecutionContext) {
    return super.canActivate(context);
  }

  handleRequest(err: any, user: any, _info: any) {
    if (err || !user) {
      throw err || new UnauthorizedException();
    }
    return user;
  }
}

import {
  Controller,
  Get,
  Param,
  Res,
  NotFoundException,
  UseGuards,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import { MinioService } from '../minio/minio.service';
import type { Response } from 'express';
import { JwtAuthGuard } from '../common/guards/jwt-auth.guard';

@Controller()
export class DocumentsController {
  constructor(
    private prisma: PrismaService,
    private minio: MinioService,
  ) {}

  @UseGuards(JwtAuthGuard)
  @Get('documents/:id')
  async getDocument(@Param('id') id: string) {
    const document = await this.prisma.document.findUnique({ where: { id } });
    if (!document) throw new NotFoundException();
    return document;
  }

  @UseGuards(JwtAuthGuard)
  @Get('documents/:id/download')
  async downloadDocument(@Param('id') id: string, @Res() res: Response) {
    const document = await this.prisma.document.findUnique({ where: { id } });
    if (!document || !document.pdfUrl) throw new NotFoundException();

    try {
      const stream = await this.minio.getFileStream(document.pdfUrl);
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader(
        'Content-Disposition',
        `attachment; filename="${document.referenceId}.pdf"`,
      );
      stream.pipe(res);
    } catch (_error) {
      throw new NotFoundException('File not found in storage');
    }
  }

  // Public endpoint
  @Get('verify/:token')
  async verifyDocument(@Param('token') token: string) {
    const verification = await this.prisma.documentVerification.findUnique({
      where: { token },
      include: { document: true },
    });

    if (!verification) {
      throw new NotFoundException('Invalid verification token');
    }

    const metadata: any = verification.document.metadata || {};

    return {
      documentId: verification.document.id,
      referenceId: verification.document.referenceId,
      status: verification.document.status,
      type: verification.document.type,
      createdAt: verification.document.createdAt,
      verifiedAt: new Date(),
      customerName: metadata.customerName || 'N/A',
      totalAmount: metadata.totalAmount || 0,
      hash: metadata.hash || 'N/A',
      revision: metadata.revision || 1,
    };
  }
}

import {
  Injectable,
  NotFoundException,
  BadRequestException,
} from '@nestjs/common';
import { PrismaService } from '../prisma/prisma.service';
import {
  CreateInvoiceDto,
  RecordPaymentDto,
  InvoiceItemDto,
} from './dto/create-invoice.dto';
import { UpdateInvoiceDto } from './dto/update-invoice.dto';
import {
  InvoiceStatus,
  PaymentStatus,
  InvoiceType,
  DiscountType,
} from '@prisma/client';
import { PdfService } from '../pdf/pdf.service';

@Injectable()
export class InvoicesService {
  constructor(
    private prisma: PrismaService,
    private pdfService: PdfService,
  ) {}

  async create(dto: CreateInvoiceDto, userId?: string) {
    const { items, ...invoiceData } = dto;
    const invoice = await this.prisma.invoice.create({
      data: {
        ...invoiceData,
        items: items
          ? {
              create: items.map((item, idx) => ({
                ...item,
                sortOrder: item.sortOrder ?? idx,
              })),
            }
          : undefined,
        createdById: userId,
      },
    });

    if (items && items.length > 0) {
      await this.recalculateTotals(invoice.id);
    }
    return this.findOne(invoice.id);
  }

  async createFromQuotation(
    quotationId: string,
    type: InvoiceType,
    userId?: string,
  ) {
    const q = await this.prisma.quotation.findUnique({
      where: { id: quotationId },
      include: {
        items: { include: { product: true, serviceItem: true } },
        terms: true,
      },
    });

    if (!q) throw new NotFoundException('Quotation not found');
    if (!['APPROVED', 'ACCEPTED', 'SENT_TO_CUSTOMER'].includes(q.status)) {
      throw new BadRequestException(
        'Quotation must be approved or accepted to convert to invoice',
      );
    }

    const termText = q.terms.map((t) => t.content).join('\n\n');

    const invoice = await this.prisma.invoice.create({
      data: {
        invoiceType: type,
        companyId: q.companyId,
        branchId: q.branchId,
        customerId: q.customerId,
        contactId: q.contactId,
        quotationId: q.id,
        quotationRevision: q.revisionNumber,
        serviceTypeId: q.serviceTypeId,
        currency: q.currency,
        notes: q.internalNotes,
        terms: termText,
        createdById: userId,
      },
    });

    if (q.items.length > 0) {
      const itemsData = q.items.map((i, idx) => ({
        invoiceId: invoice.id,
        itemType: i.itemType,
        productId: i.productId,
        serviceItemId: i.serviceItemId,
        sectionTitle: i.sectionTitle,
        description:
          i.itemType === 'SECTION_HEADING'
            ? i.sectionTitle || 'Section'
            : i.description ||
              i.product?.productName ||
              i.serviceItem?.serviceName ||
              i.sectionTitle ||
              'Item',
        quantity: i.quantity,
        unit: i.unit,
        unitPrice: i.unitPrice,
        discountType: i.discountType,
        discountValue: i.discountValue,
        discountAmount: i.discountAmount,
        taxRate: i.taxRate,
        taxAmount: i.taxAmount,
        lineTotal: i.lineTotal,
        sortOrder: i.sortOrder ?? idx,
      }));
      await this.prisma.invoiceItem.createMany({ data: itemsData });

      // Update invoice totals based on quotation
      await this.prisma.invoice.update({
        where: { id: invoice.id },
        data: {
          subtotal: q.subtotal,
          discountType: q.discountType,
          discountValue: q.discountValue,
          discountAmount: q.discountAmount,
          taxAmount: q.taxAmount,
          grandTotal: q.grandTotal,
          balanceAmount: q.grandTotal,
        },
      });
    }

    return this.findOne(invoice.id);
  }

  async findAll(companyId: string, filters: any = {}) {
    return this.prisma.invoice.findMany({
      where: { companyId, ...filters },
      include: { customer: true },
      orderBy: { createdAt: 'desc' },
    });
  }

  async findOne(id: string) {
    const invoice = await this.prisma.invoice.findUnique({
      where: { id },
      include: {
        company: {
          include: {
            bankAccounts: true,
          },
        },
        customer: true,
        contact: true,
        quotation: { select: { quotationNumber: true, projectTitle: true } },
        serviceType: true,
        items: {
          orderBy: { sortOrder: 'asc' },
          include: { product: true, serviceItem: true },
        },
        payments: {
          include: { receipt: true },
          orderBy: { paymentDate: 'desc' },
        },
      },
    });
    if (!invoice) throw new NotFoundException('Invoice not found');
    return invoice;
  }

  async update(id: string, dto: UpdateInvoiceDto) {
    const inv = await this.prisma.invoice.findUnique({ where: { id } });
    if (!inv) throw new NotFoundException();
    if (inv.invoiceStatus !== InvoiceStatus.DRAFT) {
      throw new BadRequestException(
        'Only DRAFT invoices can be freely modified',
      );
    }

    const { items, ...updateData } = dto;
    await this.prisma.invoice.update({
      where: { id },
      data: updateData as any,
    });
    return this.findOne(id);
  }

  async replaceItems(id: string, itemsDto: InvoiceItemDto[]) {
    const inv = await this.prisma.invoice.findUnique({ where: { id } });
    if (!inv || inv.invoiceStatus !== InvoiceStatus.DRAFT)
      throw new BadRequestException('Invoice not draft');

    await this.prisma.invoiceItem.deleteMany({ where: { invoiceId: id } });

    const itemsData = itemsDto.map((item, index) => {
      let discountAmount = 0;
      const qty = item.quantity || 1;
      const price = item.unitPrice || 0;
      const taxRate = item.taxRate || 0;

      if (item.discountValue) {
        if (item.discountType === DiscountType.PERCENTAGE)
          discountAmount = qty * price * (item.discountValue / 100);
        else discountAmount = item.discountValue;
      }
      const beforeTax = qty * price - discountAmount;
      const taxAmount = beforeTax * (taxRate / 100);
      return {
        ...item,
        invoiceId: id,
        sortOrder: item.sortOrder ?? index,
        discountAmount,
        taxAmount,
        lineTotal: beforeTax + taxAmount,
      };
    });

    await this.prisma.invoiceItem.createMany({ data: itemsData });
    await this.recalculateTotals(id);
    return this.findOne(id);
  }

  private async recalculateTotals(id: string) {
    const inv = await this.prisma.invoice.findUnique({
      where: { id },
      include: { items: true },
    });
    if (!inv) return;

    let subtotal = 0,
      taxAmount = 0;
    inv.items.forEach((item) => {
      const qty = item.quantity || 1;
      const price = item.unitPrice || 0;
      subtotal += qty * price - (item.discountAmount || 0);
      taxAmount += item.taxAmount || 0;
    });

    let qDiscountAmount = 0;
    if (inv.discountValue) {
      if (inv.discountType === DiscountType.PERCENTAGE)
        qDiscountAmount = subtotal * (inv.discountValue / 100);
      else qDiscountAmount = inv.discountValue;
    }

    const grandTotal = subtotal - qDiscountAmount + taxAmount;
    const balanceAmount = grandTotal - inv.paidAmount;

    await this.prisma.invoice.update({
      where: { id },
      data: {
        subtotal,
        discountAmount: qDiscountAmount,
        taxAmount,
        grandTotal,
        balanceAmount,
      },
    });
  }

  async issue(id: string) {
    const inv = await this.prisma.invoice.findUnique({
      where: { id },
      include: { company: true },
    });
    if (!inv || inv.invoiceStatus !== InvoiceStatus.DRAFT)
      throw new BadRequestException('Not in DRAFT state');

    const prefix = inv.company.invoicePrefix || 'INV';
    const year = new Date().getFullYear();
    const count = await this.prisma.invoice.count({
      where: {
        companyId: inv.companyId,
        invoiceDate: {
          gte: new Date(`${year}-01-01`),
          lte: new Date(`${year}-12-31`),
        },
        invoiceStatus: { not: InvoiceStatus.DRAFT },
      },
    });

    const seq = (count + 450 + 1).toString().padStart(4, '0');
    const invoiceNumber = `${prefix}-${year}-${seq}`;

    await this.prisma.invoice.update({
      where: { id },
      data: {
        invoiceNumber,
        invoiceStatus: InvoiceStatus.ISSUED,
        invoiceDate: new Date(),
      },
    });

    return this.findOne(id);
  }

  async recordPayment(id: string, dto: RecordPaymentDto, userId?: string) {
    const inv = await this.findOne(id);
    if (
      !inv ||
      inv.invoiceStatus === InvoiceStatus.DRAFT ||
      inv.invoiceStatus === InvoiceStatus.CANCELLED
    ) {
      throw new BadRequestException('Cannot pay Draft or Cancelled invoice');
    }

    if (dto.amount <= 0 || dto.amount > inv.balanceAmount + 0.01) {
      throw new BadRequestException(
        `Payment amount ${dto.amount} is invalid or exceeds balance ${inv.balanceAmount}`,
      );
    }

    const payment = await this.prisma.payment.create({
      data: {
        invoiceId: id,
        amount: dto.amount,
        paymentMethod: dto.paymentMethod,
        referenceNumber: dto.referenceNumber,
        notes: dto.notes,
        attachmentUrl: dto.attachmentUrl,
        paymentDate: dto.paymentDate ? new Date(dto.paymentDate) : new Date(),
        receivedByUserId: userId,
      },
    });

    // Generate receipt
    const year = new Date().getFullYear();
    const receiptCount = await this.prisma.paymentReceipt.count();
    const receiptNumber = `REC-${year}-${(receiptCount + 1).toString().padStart(5, '0')}`;

    await this.prisma.paymentReceipt.create({
      data: { paymentId: payment.id, receiptNumber },
    });

    const newPaidAmount = inv.paidAmount + dto.amount;
    const newBalanceAmount = inv.grandTotal - newPaidAmount;

    let paymentStatus: PaymentStatus = PaymentStatus.PARTIALLY_PAID;
    if (newBalanceAmount <= 0.01) paymentStatus = PaymentStatus.PAID;

    let invoiceStatus: InvoiceStatus = inv.invoiceStatus;
    if (paymentStatus === PaymentStatus.PAID)
      invoiceStatus = InvoiceStatus.PAID;
    else if (paymentStatus === PaymentStatus.PARTIALLY_PAID)
      invoiceStatus = InvoiceStatus.PARTIALLY_PAID;

    await this.prisma.invoice.update({
      where: { id },
      data: {
        paidAmount: newPaidAmount,
        balanceAmount: newBalanceAmount,
        paymentStatus,
        invoiceStatus,
      },
    });

    return this.findOne(id);
  }

  async generatePdf(id: string, _userId: string): Promise<Buffer> {
    const inv = await this.findOne(id);

    const pdfBuffer = await this.pdfService.generatePdfSync(
      'invoice-standard',
      inv.id,
      'invoiceId',
    );

    return pdfBuffer;
  }

  async remove(id: string) {
    const invoice = await this.findOne(id);
    if (!invoice) {
      throw new NotFoundException('Invoice not found');
    }
    return this.prisma.invoice.delete({ where: { id } });
  }
}

import { Processor, WorkerHost } from '@nestjs/bullmq';
import { Job } from 'bullmq';
import { chromium } from 'playwright';
import { PrismaService } from '../prisma/prisma.service';
import { MinioService } from '../minio/minio.service';
import * as crypto from 'crypto';

@Processor('pdf-generation')
export class PdfProcessor extends WorkerHost {
  constructor(
    private prisma: PrismaService,
    private minio: MinioService,
  ) {
    super();
  }

  async process(job: Job<any, any, string>): Promise<any> {
    const {
      documentId,
      templateId,
      userId,
      customerName,
      totalAmount,
      quotationId,
    } = job.data;

    // Build render URL — service-specific templates use dedicated routes,
    // all others fall through to the generic [templateId] route.
    const SERVICE_TEMPLATE_ROUTES: Record<string, string> = {
      'home-automation': 'home-automation',
      'smart-home': 'home-automation',
      'smart-home-automation': 'home-automation',
      'building-automation': 'building-automation',
      bms: 'building-automation',
      'software-development': 'software-development',
      software: 'software-development',
      'web-development': 'software-development',
      'it-infrastructure': 'it-infrastructure',
      'it-infra': 'it-infrastructure',
      network: 'it-infrastructure',
    };
    const routeSegment = SERVICE_TEMPLATE_ROUTES[templateId] || templateId;
    const qParam = quotationId ? `&quotationId=${quotationId}` : '';
    const baseUrl = process.env.FRONTEND_URL || 'http://localhost:3000';
    const renderUrl = `${baseUrl}/render-pdf/${routeSegment}?docId=${documentId}${qParam}`;

    try {
      const browser = await chromium.launch({
        headless: true,
        args: [
          '--no-sandbox',
          '--disable-setuid-sandbox',
          '--disable-dev-shm-usage',
        ],
      });
      const page = await browser.newPage();

      await page.goto(renderUrl, { waitUntil: 'networkidle' });

      const pdfBuffer = await page.pdf({
        format: 'A4',
        printBackground: true,
        margin: { top: '0mm', right: '0mm', bottom: '0mm', left: '0mm' },
      });

      await browser.close();

      const hash = crypto.createHash('sha256').update(pdfBuffer).digest('hex');
      const fileName = `document-${documentId}-${Date.now()}.pdf`;

      await this.minio.uploadFile(
        fileName,
        Buffer.from(pdfBuffer),
        'application/pdf',
      );

      const token = crypto.randomBytes(16).toString('hex');

      await this.prisma.$transaction(async (tx) => {
        await tx.document.update({
          where: { id: documentId },
          data: {
            status: 'PUBLISHED',
            pdfUrl: fileName,
            metadata: {
              hash,
              customerName,
              totalAmount,
            },
          },
        });

        await tx.documentVerification.create({
          data: {
            documentId: documentId,
            token,
          },
        });
      });

      return { success: true, fileName, hash, token };
    } catch (error) {
      console.error(`Error processing PDF job ${job.id}:`, error);
      await this.prisma.document.update({
        where: { id: documentId },
        data: { status: 'FAILED' },
      });
      throw error;
    }
  }
}

